    data.summarizedFloorCursor = clampInt(data.summarizedFloorCursor, 0, 999999, 0);
    data.lastRecallCacheKey = typeof data.lastRecallCacheKey === 'string' ? data.lastRecallCacheKey : '';
    data.lastRecalledEventIds = Array.isArray(data.lastRecalledEventIds) ? data.lastRecalledEventIds.filter(function (id) {
      return typeof id === 'string';
    }) : [];
